import test from 'node:test';
import assert from 'node:assert/strict';
import {marketResearchFixture} from './helpers/market-research-fixture.mjs';
import {exitFixture} from './helpers/market-exit-fixture.mjs';
import {planRenewal} from '../server/market-plan-renewal.mjs';
import {digest} from '../server/codex-research.mjs';
const valid=c=>assert.equal(c.eligible,true,c.reasons.join(';'));
const windowQuote=(f,day='2026-10-09',price='100')=>{const at=f.at(),close=day+'T20:00:00Z';return f.quote(price,{sessionOpen:day+'T13:30:00Z',sessionClose:close,validUntil:close,fx:{id:'renewal-fx',source:'synthetic-only',usdPerUnit:'1',asOf:at,receivedAt:at,validUntil:close}});};
const extend=(r,p)=>{for(const a of r.companyAssessments){a.recommendation.validUntil='2026-10-10T19:00:00Z';a.recommendation.holdingHorizon.until='2026-10-11T14:00:00Z';}r.rawOutput=JSON.stringify({sections:r.sections,missingEvidence:r.missingEvidence,companyAssessments:r.companyAssessments});r.trace.outputHash=digest(r.rawOutput);return r;};
async function nextSession(f){f.tick(86400000);windowQuote(f);f.sim.process();await f.observe();}
test('expired automatic plan waits for a new session, is read-only and needs a new final approval',async()=>{
 const f=await marketResearchFixture({transformDossier:extend});try{f.enable();const c=f.candidate();valid(c);f.decide(c);const original=structuredClone(f.sim.snapshot().orders[0]);f.tick(3601000);f.quote();f.sim.process();await f.observe();assert.equal(f.candidate().id,c.id);assert.equal(f.candidate().eligible,false);await nextSession(f);const changes=f.store.db.prepare('SELECT total_changes() n').get().n,n=f.candidate();valid(n);assert.notEqual(n.id,c.id);assert.equal(n.continuation.trigger.kind,'market-session');assert.equal(n.continuation.previousOrderId,original.id);assert.equal(f.sim.snapshot().orders.length,1);assert.equal(f.store.db.prepare('SELECT total_changes() n').get().n,changes);f.tick();windowQuote(f,'2026-10-09','99');const refreshed=f.candidate();assert.equal(refreshed.id,n.id);assert.throws(()=>f.decide(n),/依据已变化/);f.decide(refreshed);let b=f.sim.process();assert.equal(b.fills.length,0);assert.equal(b.orders[1].status,'approved');f.tick();windowQuote(f,'2026-10-09','99');b=f.sim.process();assert.equal(b.orders[1].status,'filled');assert.equal(b.orders[0].status,'expired');assert.equal(b.researchDecisions.length,2);assert.deepEqual(b.orders[0].approval,original.approval);assert.equal(f.service.snapshot().overview.decisions.length,0);}finally{await f.close();}
});
test('partial buy renewal caps remaining quantity and fee-inclusive remaining budget even after a price drop',async()=>{
 const f=await marketResearchFixture({transformDossier:extend});try{f.enable();const c=f.candidate();f.decide(c);f.tick();f.quote('100',{availableBuy:100});let b=f.sim.process();const o=b.orders[0],fills=structuredClone(b.fills);assert.equal(o.filledQty,100);await nextSession(f);windowQuote(f,'2026-10-09','90');const n=f.candidate();valid(n);assert.equal(n.order.qty,o.qty-100);assert(n.order.budgetCents<=o.budgetCents-o.spentCents);assert(n.estimate.netCents<=n.order.budgetCents);f.decide(n);f.tick();windowQuote(f,'2026-10-09','90');b=f.sim.process();assert.equal(b.orders[1].status,'filled');assert.equal(b.lots.reduce((n,l)=>n+l.qty,0),o.qty);assert.deepEqual(b.fills.slice(0,fills.length),fills);assert.equal(f.candidate().eligible,false);}finally{await f.close();}
});
test('partial reduction renews the unfinished target rather than halving the remainder again',async()=>{
 const f=await marketResearchFixture({transformDossier:extend});try{f.enable();f.decide(f.candidate());f.tick();f.quote();f.sim.process();await f.save('reduce');const c=f.candidate();valid(c);f.decide(c);f.tick();f.quote('100',{availableSell:40});const b=f.sim.process(),o=b.orders.at(-1);assert.equal(o.filledQty,40);await nextSession(f);const n=f.candidate();valid(n);assert.equal(n.order.qty,o.qty-40);assert.deepEqual(n.order.targetLotIds,o.targetLotIds);f.decide(n);f.tick();windowQuote(f);const after=f.sim.process();assert.equal(after.orders.at(-1).status,'filled');assert.equal(after.lots.reduce((n,l)=>n+l.qty,0),249-o.qty);assert.equal(f.candidate().eligible,false);}finally{await f.close();}
});
test('rejected, cancelled and fully filled plans do not restart in another session; renewal rejection stays final',async()=>{
 for(const state of ['reject','cancel','filled','renewal-reject']){const f=await marketResearchFixture({transformDossier:extend});try{f.enable();const c=f.candidate();f.decide(c,state==='reject'?'reject':'approve');if(state==='cancel'){const o=f.sim.snapshot().orders[0];f.sim.decide(o.id,f.command({action:'cancel',note:'本人撤销'}));}if(state==='filled'){f.tick();f.quote();f.sim.process();}await nextSession(f);if(state==='renewal-reject'){const n=f.candidate();valid(n);f.decide(n,'reject');f.tick(3600000);windowQuote(f);await f.observe();assert.equal(f.candidate().id,n.id);}else assert.equal(f.candidate().id,c.id);assert.equal(f.candidate().eligible,false);assert.equal(f.service.snapshot().overview.decisions.length,0);}finally{await f.close();}}
});
test('new condition episode must be persisted after terminal time, never a quote tick or unknown recovery',()=>{
 const order={id:'order',status:'invalidated',endedAt:'2026-10-08T14:30:00Z',qty:100,filledQty:30,side:'buy',budgetCents:10000,spentCents:3000},check={id:'check',episode:1},decision={candidateId:'base',orderId:'order',action:'approve',basis:{checks:[check],quote:{sessionOpen:'2026-10-08T13:30:00Z'}}},args={baseId:'base',decisions:[decision],orders:[order],at:'2026-10-08T15:00:00Z',quote:{sessionOpen:'2026-10-08T13:30:00Z'},trigger:{id:'check',current:true,status:'true',episode:2,lastHitAt:'2026-10-08T14:31:00Z'}};
 const n=planRenewal(args);assert.equal(n.continuation.trigger.kind,'condition-episode');assert.equal(n.continuation.remainingQty,70);assert.equal(n.continuation.remainingBudgetCents,7000);for(const patch of [{episode:1},{current:false},{status:'unknown'},{lastHitAt:'2026-10-08T14:29:00Z'},{lastHitAt:'2026-10-08T15:01:00Z'}])assert.equal(planRenewal({...args,trigger:{...args.trigger,...patch}}).continuation,null);assert.equal(planRenewal({...args,orders:[{...order,endedAt:null}]}).continuation,null);
});
test('stale research, paused observations, future session and invalid quotes cannot make a renewal actionable',async()=>{
 for(const change of [f=>f.service.controlOperation('observations','pause'),f=>f.service.research.update(f.topic.id,{version:f.topic.version,nextEvidence:'来源或判断更新'}),f=>windowQuote(f,'2026-10-10'),f=>f.setQuotes({})]){const f=await marketResearchFixture({transformDossier:extend});try{f.enable();f.decide(f.candidate());await nextSession(f);change(f);const n=f.candidate();assert.equal(n.eligible,false);assert.equal(f.service.snapshot().overview.decisions.length,0);assert.throws(()=>f.decide(n));assert.equal(f.sim.snapshot().orders.length,1);}finally{await f.close();}}
});
test('risk exit renewal tracks original batches after a partial fill and requires a separate approval',async()=>{
 const f=exitFixture();try{f.buy();f.tick();f.quote('85');const c=f.candidate();f.decide(c);f.tick();f.quote('85',{availableSell:40});f.sim.process();assert.equal(f.candidate().id,c.id);assert.equal(f.service.snapshot().overview.decisions.length,0);f.setTime('2026-10-07T13:45:00Z');windowQuote(f,'2026-10-07','85');f.sim.process();const n=f.candidate();valid(n);assert(n.continuation);assert.equal(n.order.qty,60);assert.notEqual(n.id,c.id);f.decide(n);f.tick();windowQuote(f,'2026-10-07','85');const b=f.sim.process();assert.equal(b.lots.length,0);assert.equal(b.exitDecisions.length,2);assert.equal(b.orders.at(-1).status,'filled');}finally{await f.close();}
});
test('failed renewal decision rolls back and exact request replay never duplicates a new order',async()=>{
 const f=await marketResearchFixture({transformDossier:extend});try{f.enable();f.decide(f.candidate());await nextSession(f);const n=f.candidate();valid(n);const before=f.sim.snapshot();f.store.db.exec("CREATE TEMP TRIGGER fail_renewal BEFORE INSERT ON market_sim_events_steady BEGIN SELECT RAISE(ABORT,'renewal failure'); END");assert.throws(()=>f.decide(n),/renewal failure/);assert.deepEqual(f.sim.snapshot(),before);f.store.db.exec('DROP TRIGGER fail_renewal');const data=f.command({action:'approve',fingerprint:n.fingerprint,note:'合成重新决定',confirmSimulation:true});const b=f.sim.decideResearch(n.id,data);assert.equal(f.sim.decideResearch(n.id,data).version,b.version);assert.equal(f.sim.snapshot().orders.length,2);}finally{await f.close();}
});
test('real saved condition episodes produce one same-session successor only after observed false then true',async()=>{
 const f=await marketResearchFixture({transformDossier:(r,p)=>{extend(r,p);r.companyAssessments[0].monitoring.entryCondition.conditions=[{type:'price',interval:'1m',operator:'lte',value:100}];r.rawOutput=JSON.stringify({sections:r.sections,missingEvidence:r.missingEvidence,companyAssessments:r.companyAssessments});r.trace.outputHash=digest(r.rawOutput);return r;}});
 try{f.store.addWatch('NVDA.US');f.service.controlOperation('minutes','resume');const observed=async price=>{const time=f.at().slice(0,16).replace('T',' '),q={symbol:'NVDA.US',currency:'USD',provider:'yahoo-public-chart',providerTimezone:'UTC',providerTime:time,points:[{time,close:price}]};f.store.db.prepare('INSERT OR REPLACE INTO quotes VALUES(?,?,?)').run(q.symbol,JSON.stringify(q),f.at());f.store.status(q.symbol,{state:'ok',receivedAt:f.at()});await f.observe();};
  await observed(99);f.enable();const c=f.candidate();valid(c);f.decide(c);f.tick(3601000);f.quote();f.sim.process();await observed(99);assert.equal(f.candidate().id,c.id);f.store.status('NVDA.US',{state:'error'});await f.observe();await observed(99);assert.equal(f.candidate().id,c.id);f.tick(60000);await observed(101);f.tick(60000);f.quote();await observed(99);const n=f.candidate();valid(n);assert.equal(n.continuation.trigger.kind,'condition-episode');assert.equal(n.continuation.trigger.episode,2);assert.equal(f.sim.snapshot().orders.length,1);await observed(99);assert.equal(f.candidate().id,n.id);
 }finally{await f.close();}
});
test('fully consumed batches in a partial strategy exit do not create a second visible decision',async()=>{
 const f=exitFixture();try{f.buy();f.buy();f.tick();f.quote('85');const c=f.candidate();assert.equal(c.order.qty,200);f.decide(c);f.tick();f.quote('85',{availableSell:100});const b=f.sim.process();assert.equal(b.lots.length,1);assert.equal(f.candidate().id,c.id);assert.equal(f.service.snapshot().overview.decisions.length,0);f.setTime('2026-10-07T13:45:00Z');windowQuote(f,'2026-10-07','85');f.sim.process();const n=f.candidate();valid(n);assert.equal(n.order.qty,100);assert.equal(n.continuation.remainingQty,100);assert.deepEqual(n.order.targetLotIds,b.lots.map(l=>l.id));}finally{await f.close();}
});
test('HTTP preserves renewal explanation and lineage while diagnostic causes remain hidden',async()=>{
 const f=await marketResearchFixture({transformDossier:extend});try{f.enable();f.decide(f.candidate());await nextSession(f);const {createHandler}=await import('../server/index.mjs');let code,body;await createHandler(f.store,f.service)({method:'GET',url:'/api/market-simulation?account=steady',headers:{host:'127.0.0.1:4179'}},{writeHead:s=>code=s,end:b=>body=JSON.parse(b)});assert.equal(code,200);const c=body.researchCandidates[0];assert.equal(c.continuation.trigger.kind,'market-session');assert.match(c.continuation.trigger.reason,/新的核验交易时段/);assert.equal(c.continuation.previousOrderId,body.orders[0].id);assert.equal(c.fingerprint,f.candidate().fingerprint);const {safeDiagnosticPayload}=await import('../shared/safe-errors.mjs');assert.equal(safeDiagnosticPayload({cause:{token:'private'}}).cause,'诊断详情已隐藏');}finally{await f.close();}
});
